            // Penalize placing current item if it blocks the next item from an otherwise perfect fit
            score += 15.0;
        }
    }

    // 3. Global State: Encourage filling bins towards the mean_residual to keep density uniform.
    let dev_from_mean = (post_residual as f64 - mean_residual).abs();
