    }

    // Lookahead logic: if the next item is large and won't fit in this post_residual, 
    // penalize this bin to save space for the next item
    if next_item_size > 0 && post < next_item_size as f64 {
        score += (next_item_size as f64 - post) * 1.5;
    }

    // New bin logic:
