    let mut score = post * post * 0.01;

    // Favor bins that leave very little space (Best Fit variant)
    // We add a penalty for "near-misses" (small post_residual but not zero)
    if post > 0.0 && post < 10.0 {
        score += 5.0 / (post + 0.1);
