    if bin_residual == bin_capacity {
        let new_bin_penalty = 45.0 + (progress * 30.0) - (open_bins_count as f64 * 0.5);
        score += new_bin_penalty;
    }

    // If this is the last chance to fit an item into an existing bin, reduce its score
    // to prevent unnecessary new bin creation.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

